/**
 * Führt einen fetch-Aufruf aus und beendet ihn nach ms Millisekunden.
 * @param {string} url - Die URL, die abgerufen werden soll.
 * @param {number} ms - Die Anzahl der Millisekunden, nach denen der Aufruf abgebrochen wird.
 * @returns {Promise<unknown>} Der Inhalt des fetch-Aufrufs, wenn er erfolgreich ist.
 */
export async function fetchMitTimeout(url, ms) {
  const timeout = new Promise((_, reject) => {
    const timer = setTimeout(() => {
      reject(new Error(`fetch abgelaufen nach ${ms} ms`));
    }, ms);
    return () => clearTimeout(timer);
  });

  try {
    const fetchPromise = fetch(url);
    const [result, _] = await Promise.all([fetchPromise, timeout]);
    return result;
  } catch (error) {
    if (error.message.includes('fetch abgelaufen')) {
      throw error;
    }
    throw error;
  }
}
```

